#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char *title;
} Book;

int find_book_index(Book *books, int n, int id) {
    for (int i = 0; i < n; ++i) {
        if (books[i].id == id) return i;
    }
    return -1;
}

int main(void) {
    Book *books = NULL;
    int capacity = 0;
    int count = 0;
    int choice;

    while (scanf("%d", &choice) == 1) {
        if (choice == 1) { /* Add */
            int id;
            char buffer[256];
            if (scanf("%d", &id) != 1) break;
            /* consume newline after id */
            int c;
            while ((c = getchar()) != '\n' && c != EOF);
            /* read title */
            if (fgets(buffer, sizeof(buffer), stdin) == NULL) break;
            size_t len = strlen(buffer);
            if (len > 0 && buffer[len - 1] == '\n') buffer[len - 1] = '\0';
            /* allocate memory for title */
            char *title = malloc(len);
            if (!title) return 1;
            strcpy(title, buffer);
            /* ensure capacity */
            if (count >= capacity) {
                int newcap = capacity == 0 ? 4 : capacity * 2;
                Book *tmp = realloc(books, newcap * sizeof(Book));
                if (!tmp) return 1;
                books = tmp;
                capacity = newcap;
            }
            books[count].id = id;
            books[count].title = title;
            count++;
            printf("Book added successfully.\n");
        } else if (choice == 2) { /* Search */
            int id;
            if (scanf("%d", &id) != 1) break;
            int idx = find_book_index(books, count, id);
            if (idx >= 0) {
                printf("Book found: ID=%d, Title=\"%s\"\n", books[idx].id, books[idx].title);
            } else {
                printf("Book not found.\n");
            }
        } else if (choice == 3) { /* Delete */
            int id;
            if (scanf("%d", &id) != 1) break;
            int idx = find_book_index(books, count, id);
            if (idx >= 0) {
                free(books[idx].title);
                for (int i = idx; i < count - 1; ++i) {
                    books[i] = books[i + 1];
                }
                count--;
                printf("Book deleted successfully.\n");
            } else {
                printf("Book not found.\n");
            }
        } else if (choice == 4) { /* Display */
            for (int i = 0; i < count; ++i) {
                printf("Book ID=%d, Title=\"%s\"\n", books[i].id, books[i].title);
            }
        } else if (choice == 5) { /* Exit */
            printf("Exiting the program...\n");
            break;
        }
    }

    /* Clean up */
    for (int i = 0; i < count; ++i) free(books[i].title);
    free(books);
    return 0;
}
